{
  "case_id": "xsu_sg_010_congenital_impairment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "De opregnede dokumenttyper svarer til vejledningen, og der er ingen direkte retsfejl. Men svaret nævner ikke, at redegørelsen kun supplerer og ikke erstatter det lægefaglige minimum. Det siger heller ikke, at de seneste oplysninger kan være ældre. Det præsenterer desuden listen som et konkret katalog uden at sige, at eksemplerne ikke er obligatoriske eller udtømmende. Rubrikken kræver disse forbehold for en korrekt fremstilling."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Sygehistorik, journalnotater, epikriser, støtteforanstaltninger/skånehensyn og personlig redegørelse er med. Svaret mangler dog at nævne beskrivelsen af udrednings- og behandlingsforløb samt eventuelle aktuelle symptomer, som er et kritisk element. Det nævner heller ikke, at nyere dokumentation om aktuelt funktionsniveau ofte mangler."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret angiver direkte, hvilken dokumentation en ansøger med medfødt funktionsnedsættelse kan vedlægge. Det besvarer spørgsmålet uden irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen kilde, hverken vejledning, afsnit eller bekendtgørelse."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke citeret nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke citeret nogen kilde, så kildestøtten kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Indholdet findes i vejledningens afsnit 4.3. Svaret tilføjer ingen ny regel, betingelse eller myndighed. Forklaringen af 'epikriser' i parentes er en neutral definition."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret fremhæver ikke, at eksemplerne ikke er kumulative krav, og at de seneste oplysninger kan være ældre. Det nævner ikke, at den personlige redegørelse kun supplerer og ikke ophæver det lægefaglige dokumentationsminimum. Det angiver også, at redegørelsen kan bruges 'hvis der ikke er dokumentation tilgængelig', hvilket kan læses som en erstatning."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er en enkel og konsistent opremsning, og konklusionen følger af den."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Svaret bruger 'kan' i stedet for 'skal' og gør ikke eksemplerne til absolutte krav. Det udtrykker dog ikke vejledningens 'det er vigtigt', og det angiver ikke eksplicit, at der ikke er krav om alle typer."
    }
  },
  "xhaile_coverage": {
    "A49": {
      "label": "partial",
      "reason": "Svaret dækker sygehistorik, de seneste journalnotater og den personlige redegørelse. Det forklarer ikke, hvad medfødt funktionsnedsættelse er, eller at nyere dokumentation ofte mangler. Eksemplerne på diagnoser er heller ikke med."
    },
    "A35": {
      "label": "partial",
      "reason": "Svaret dækker de fleste dokumentationsformer, epikriser, journalnoter, afgørelser, skånehensyn og den personlige redegørelse. Det udelader dog udrednings- og behandlingsforløb samt aktuelle symptomer, ansøgningstidspunktet og forbeholdene om, at oplysningerne er de seneste foreliggende."
    }
  },
  "overall_notes": "Svaret gengiver i store træk vejledningens eksempler korrekt, men det er ukildebelagt. Det mangler flere kritiske elementer og de forbehold, som rubrikken kræver: at eksemplerne ikke er obligatoriske, at oplysningerne kan være ældre, og at redegørelsen kun supplerer. C05 og C06 er not_assessable, fordi der ikke er angivet nogen kilde."
}

